<script setup>
import { vCanAction } from '../../../services/permission-directives.js'
import { vAuthSrc, vAuthHref } from '../authenticated-media.js'
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {api,messageOf,socket} from '../services'
const catalogs=ref([]),selectedId=ref(''),catalog=ref(null),products=ref([]),orders=ref([]),tab=ref('products'),search=ref(''),error=ref(''),notice=ref(''),busy=ref(false),form=ref(null),saving=ref(false),creating=ref(false),newCatalog=ref({title:'',slug:'',description:''}),orderFilter=ref('submitted')
const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const shown=computed(()=>products.value.filter(p=>`${p.code} ${p.name} ${p.category}`.toLowerCase().includes(search.value.toLowerCase())))
const publicUrl=computed(()=>catalog.value?`${location.origin}/comunicacao/app/whatsapp-web/catalogo/${catalog.value.slug}`:'')
async function load(){try{catalogs.value=(await api.get('/catalog')).data.items;if(!selectedId.value&&catalogs.value.length)selectedId.value=catalogs.value[0]._id;if(selectedId.value)await select()}catch(e){error.value=messageOf(e)}}
async function select(){catalog.value=JSON.parse(JSON.stringify(catalogs.value.find(c=>c._id===selectedId.value)));if(!catalog.value)return;products.value=(await api.get(`/catalog/${selectedId.value}/products`)).data.items;await loadOrders()}
async function loadOrders(){if(!selectedId.value)return;try{orders.value=(await api.get(`/catalog/${selectedId.value}/orders`,{params:{status:orderFilter.value}})).data.items}catch(e){error.value=messageOf(e)}}
async function createCatalog(){busy.value=true;try{const result=await api.post('/catalog',newCatalog.value);selectedId.value=result.data._id;creating.value=false;await load()}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
async function saveCatalog(){busy.value=true;error.value='';try{await api.put(`/catalog/${selectedId.value}`,catalog.value);notice.value='Catálogo atualizado.';await load()}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
function edit(p){form.value=p?{...p,price:(p.priceCents/100).toFixed(2)}:{code:'ITEM'+(products.value.length+1),name:'',description:'',category:'Produtos',kind:'product',price:'0.00',stock:'',published:true,featured:false,media:[]}}
async function saveProduct(){saving.value=true;error.value='';try{const body={...form.value,priceCents:Math.round(Number(String(form.value.price).replace(',','.'))*100)};const result=form.value._id?await api.put(`/catalog/${selectedId.value}/products/${form.value._id}`,body):await api.post(`/catalog/${selectedId.value}/products`,body);form.value={...form.value,...result.data,media:form.value.media||[]};await select();notice.value='Item salvo. Você já pode anexar mídias.'}catch(e){error.value=messageOf(e)}finally{saving.value=false}}
async function upload(event){const file=event.target.files?.[0];if(!file||!form.value?._id)return;saving.value=true;try{const data=new FormData();data.append('file',file);const result=(await api.post(`/catalog/${selectedId.value}/products/${form.value._id}/media`,data)).data;form.value.media.push({...result,kind:file.type.split('/')[0],name:file.name});await select();form.value.updatedAt=products.value.find(p=>p._id===form.value._id)?.updatedAt}catch(e){error.value=messageOf(e)}finally{saving.value=false;event.target.value=''}}
async function unattach(m){try{await api.delete(`/catalog/${selectedId.value}/products/${form.value._id}/media/${m.id}`);form.value.media=form.value.media.filter(x=>x.id!==m.id);await select();form.value.updatedAt=products.value.find(p=>p._id===form.value._id)?.updatedAt}catch(e){error.value=messageOf(e)}}
async function archive(p){if(!confirm(`Ocultar e arquivar ${p.name}? Pedidos já enviados serão preservados.`))return;try{await api.delete(`/catalog/${selectedId.value}/products/${p._id}`);await select()}catch(e){error.value=messageOf(e)}}
async function copyUrl(){try{await navigator.clipboard.writeText(publicUrl.value);notice.value='Link copiado.'}catch{notice.value=publicUrl.value}}
onMounted(()=>{load();socket.on('catalog:order',loadOrders)});onBeforeUnmount(()=>socket.off('catalog:order',loadOrders))
</script>
<template><section><header class="page-head"><div><span class="eyebrow">Produtos, serviços e pedidos</span><h1>Catálogo</h1><p>Cadastre seu negócio e escolha o que o cliente vê no catálogo público.</p></div><button v-can-action="'web_catalog.create'" class="btn secondary" @click="creating=true">＋ Novo catálogo</button></header><p v-if="error" class="catalog-error" role="alert">{{error}}</p><p v-if="notice" class="catalog-notice" role="status">{{notice}}</p><div class="catalog-bar card"><select v-model="selectedId" @change="select" aria-label="Selecionar catálogo"><option v-for="c in catalogs" :key="c._id" :value="c._id">{{c.title}}</option></select><div class="catalog-tabs"><button v-for="t in [['products','Itens'],['settings','Página pública'],['orders','Pedidos']]" :key="t[0]" class="btn" :class="{secondary:tab!==t[0]}" @click="tab=t[0]">{{t[1]}}</button></div><a v-if="catalog" class="btn secondary" v-auth-href="publicUrl" target="_blank" rel="noopener">↗ Abrir catálogo</a></div><template v-if="catalog"><div v-if="tab==='products'"><div class="items-bar"><input v-model="search" placeholder="Buscar por nome, categoria ou ID"><button v-can-action="'web_catalog.create'" class="btn" @click="edit(null)">＋ Novo item</button></div><div class="catalog-grid"><article v-for="p in shown" :key="p._id" class="card item-card"><img v-if="p.media?.[0]?.kind==='image'" v-auth-src="p.media[0].url" :alt="p.name" loading="lazy"><video v-else-if="p.media?.[0]?.kind==='video'" v-auth-src="p.media[0].url" controls preload="metadata" class="item-video"></video><div v-else class="item-placeholder">{{p.kind==='service'?'⚙':'🍽'}}</div><div><span class="item-code">{{p.code}}</span><h2>{{p.name}}</h2><p>{{p.category}} · {{p.kind==='service'?'Serviço':'Produto'}}</p><strong>{{money(p.priceCents)}}</strong><small>{{p.stock==null?'Estoque ilimitado':p.stock+' em estoque'}} · {{p.published?'Publicado':'Oculto'}}</small><footer><button v-can-action="'web_catalog.edit'" class="btn secondary" @click="edit(p)">Editar</button><button v-can-action="'web_catalog.delete'" class="btn secondary" @click="archive(p)">Arquivar</button></footer></div></article></div><p v-if="!shown.length">Nenhum item encontrado.</p></div><form v-else-if="tab==='settings'" class="card catalog-settings" @submit.prevent="saveCatalog"><h2>Página pública e regras de exibição</h2><div class="two-fields"><label>Nome do catálogo<input v-model="catalog.title" required maxlength="120"></label><label>Endereço curto (slug)<input v-model="catalog.slug" required pattern="[a-z0-9-]{2,60}"></label></div><label>Apresentação<textarea v-model="catalog.description" maxlength="2000"></textarea></label><div class="two-fields"><label>Endereço de retirada<input v-model="catalog.pickupAddress" maxlength="500"></label><label>Taxa de entrega (R$)<input :value="(catalog.deliveryFeeCents/100).toFixed(2)" type="number" min="0" step="0.01" @input="catalog.deliveryFeeCents=Math.round(Number($event.target.value)*100)"></label></div><label class="toggle"><input v-model="catalog.published" type="checkbox">Publicar catálogo (acesso sem login)</label><div class="visibility-options"><label v-for="f in [['description','Descrição'],['price','Preço'],['stock','Quantidade em estoque'],['media','Imagens e mídias']]" :key="f[0]" class="toggle"><input v-model="catalog.publicFields[f[0]]" type="checkbox">Mostrar {{f[1]}}</label></div><small>Nome e ID identificam os itens publicados. Preços ocultos impedem pedidos automáticos desses itens. Mídias ficam públicas apenas enquanto o catálogo e o item estiverem publicados.</small><div class="public-link"><code>{{publicUrl}}</code><button class="btn secondary" type="button" @click="copyUrl">Copiar link</button></div><button v-can-action="'web_catalog.edit'" class="btn" :disabled="busy">Salvar catálogo</button></form><div v-else class="catalog-orders"><header><h2>Pedidos por contato</h2><select v-model="orderFilter" @change="loadOrders" aria-label="Filtrar pedidos"><option value="submitted">Enviados</option><option value="draft">Em montagem</option><option value="finalizing">Finalizando</option></select><button class="btn secondary" @click="loadOrders">Atualizar</button></header><article v-for="o in orders" :key="o._id" class="card order-card"><div><strong>{{o.number}}</strong><small>{{o.chat?.displayName}} · {{o.chat?.phone}}</small></div><span>{{o.status==='submitted'?'Enviado':o.status==='draft'?'Em montagem':'Finalizando'}}</span><ul><li v-for="i in o.items" :key="i.code">{{i.quantity}}x {{i.code}} · {{i.name}} — {{money(i.quantity*i.unitPriceCents)}}</li></ul><p>{{o.fulfillment==='pickup'?'Retirada':'Entrega'}} · {{o.address?.text||catalog.pickupAddress}}</p><a v-if="o.address?.latitude!=null" v-auth-href="`https://www.google.com/maps?q=${o.address.latitude},${o.address.longitude}`" target="_blank" rel="noopener">Abrir localização</a><strong>{{money(o.totalCents)}}</strong></article><p v-if="!orders.length">Nenhum pedido nesse estágio.</p></div></template><div v-if="creating" class="catalog-overlay" role="dialog" aria-modal="true" aria-label="Novo catálogo"><form class="card catalog-modal" @submit.prevent="createCatalog"><header><h2>Novo catálogo</h2><button type="button" class="icon-button" @click="creating=false" aria-label="Fechar">×</button></header><label>Nome<input v-model="newCatalog.title" required maxlength="120"></label><label>Endereço curto<input v-model="newCatalog.slug" required pattern="[a-z0-9-]{2,60}" placeholder="minha-loja"></label><button v-can-action="'web_catalog.create'" class="btn" :disabled="busy">Criar catálogo</button></form></div><div v-if="form" class="catalog-overlay" role="dialog" aria-modal="true" aria-label="Configurar item"><form class="card catalog-modal" @submit.prevent="saveProduct"><header><h2>{{form._id?'Editar item':'Novo item'}}</h2><button type="button" class="icon-button" @click="form=null" aria-label="Fechar">×</button></header><div class="two-fields"><label>ID usado no WhatsApp<input v-model="form.code" required pattern="[A-Za-z0-9_-]{2,24}" placeholder="BUGR1"></label><label>Tipo<select v-model="form.kind"><option value="product">Produto</option><option value="service">Serviço</option></select></label></div><label>Nome<input v-model="form.name" required maxlength="150"></label><label>Descrição<textarea v-model="form.description" maxlength="3000"></textarea></label><div class="two-fields"><label>Categoria<input v-model="form.category" required maxlength="80"></label><label>Preço (R$)<input v-model="form.price" type="number" min="0" step="0.01" required></label><label>Estoque<input v-model="form.stock" type="number" min="0" step="1" placeholder="Vazio = ilimitado"></label><div><label class="toggle"><input v-model="form.published" type="checkbox">Mostrar no catálogo</label><label class="toggle"><input v-model="form.featured" type="checkbox">Mais pedido / destaque</label></div></div><section class="upload-section"><h3>Imagens e mídias</h3><p v-if="!form._id">Salve o item para anexar mídias.</p><template v-else><label class="btn secondary">＋ Adicionar mídia<input type="file" accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm,audio/mpeg,audio/ogg,audio/wav,application/pdf" :disabled="saving" @change="upload" hidden></label><small>Até 6 arquivos de 20 MB por item.</small><div class="media-previews"><figure v-for="m in form.media" :key="m.id"><img v-if="!m.kind||m.kind==='image'" v-auth-src="m.url" alt="Prévia do item"><video v-else-if="m.kind==='video'" v-auth-src="m.url" controls preload="metadata"></video><audio v-else-if="m.kind==='audio'" v-auth-src="m.url" controls preload="metadata"></audio><a v-else v-auth-href="m.url" target="_blank">{{m.name||'Arquivo'}}</a><button type="button" @click="unattach(m)">Remover do item</button></figure></div></template></section><p v-if="error" class="catalog-error">{{error}}</p><footer><button class="btn secondary" type="button" @click="form=null">Fechar</button><button v-can-action="form._id ? 'web_catalog.edit' : 'web_catalog.create'" class="btn" :disabled="saving">{{saving?'Salvando…':'Salvar item'}}</button></footer></form></div></section></template>
<style scoped>
.catalog-bar,.items-bar,.catalog-tabs{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.catalog-bar{padding:16px;margin-bottom:24px}.catalog-bar>a{margin-left:auto}.items-bar{margin:20px 0}.items-bar input{flex:1;min-width:180px}.catalog-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.item-card{overflow:hidden}.item-card>img,.item-video,.item-placeholder{width:100%;height:210px;object-fit:cover}.item-placeholder{display:grid;place-items:center;font-size:45px;background:#123c37}.item-card>div:last-child{padding:20px}.item-card h2{font-size:19px;margin:10px 0}.item-card p,.item-card small{font-size:12px;color:#9fc9c3}.item-card small{display:block;margin-top:10px}.item-code{font:12px monospace;color:#62e7cc}.item-card footer{display:flex;gap:8px;margin-top:18px}.catalog-settings,.catalog-modal{display:grid;gap:18px;padding:26px}.catalog-settings label,.catalog-modal label{display:grid;gap:8px;font-size:13px}.catalog-settings .toggle,.catalog-modal .toggle{display:flex;align-items:center}.two-fields{display:grid;grid-template-columns:1fr 1fr;gap:15px}input,textarea,select{width:100%;padding:11px;border:1px solid #37635e;background:#0b2928;color:#e6fff9;border-radius:9px;color-scheme:dark}input[type=checkbox]{width:auto}.visibility-options{display:flex;gap:20px;flex-wrap:wrap}.public-link{display:flex;gap:15px;align-items:center;flex-wrap:wrap}.public-link code{overflow-wrap:anywhere}.catalog-overlay{position:fixed;inset:0;z-index:110;background:#001416ce;display:grid;place-items:center;padding:16px}.catalog-modal{width:min(680px,100%);max-height:94dvh;overflow:auto}.catalog-modal header,.catalog-modal footer,.catalog-orders>header{display:flex;justify-content:space-between;align-items:center;gap:12px}.catalog-modal h2{font-size:23px;margin:0}.catalog-modal small{color:#afd6cc;font-size:12px}.media-previews{display:flex;flex-wrap:wrap;gap:10px}.media-previews figure{width:150px;margin:12px 0}.media-previews img,.media-previews video{width:100%;height:120px;object-fit:cover;border-radius:10px}.media-previews audio{width:100%}.media-previews button{border:0;background:transparent;color:#ffb9ab;padding:9px 0;cursor:pointer}.catalog-error{padding:12px;background:#542729;color:#ffd8cd;border-radius:8px}.catalog-notice{padding:12px;color:#c2fff1}.order-card{padding:22px;margin-top:15px}.order-card small{display:block;margin:8px 0;color:#a8cbc4}.order-card ul{line-height:1.8}.order-card>strong{display:block;margin-top:12px;font-size:20px}.catalog-orders>header select{width:auto}@media(max-width:1000px){.catalog-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.catalog-grid,.two-fields{grid-template-columns:1fr}.catalog-bar>select{width:100%}.catalog-tabs .btn{font-size:12px}.catalog-modal{padding:20px}.catalog-orders>header{flex-wrap:wrap}.page-head{align-items:start}}
</style>
